            values.push(involvement.to_string().into());
            values.push(room_id.into());
            values.push((*user_id).into());
        }
        let mut stmt = tx.conn().prepare(&sql)?;
        let mut rows = stmt.query(rusqlite::params_from_iter(values))?;
        while rows.next()?.is_some() {}
    }
