pub fn renderer_base_url(c: &Ctx) -> String {
    format!("{}{}", c.request.protocol(), c.request.host())
}

/// Renders with the `ViewContext` `ApplicationController.render` has (no request, no
/// `Current.user`, no CSRF tokens), during a request: URLs get the request's host through
/// `default_url_options` (`SetCurrentRequest`), see [`renderer_base_url`].
pub fn render_detached_at<T>(app: &App, account: Option<&Account>, base_url: &str, render: impl FnOnce(&ViewContext) -> T) -> T {
    let asset_path = |path: &str| campfire_assets::asset_path(path);
    let stylesheets = crate::controllers::presenters::view_context::stylesheet_tags();
    let ctx = ViewContext {
        current_user: None,
        account: account_summary(account, false),
        flash_notice: None,
        flash_alert: None,
    crate::integrations::bot_webhooks::mention_later(c.app(), message.id, base_url);
    Ok(())
}

pub(crate) async fn broadcast_create_at(app: &App, room: &Room, message: &Message, base_url: String) -> Result<()> {
    let (app2, room, message) = (app.clone(), room.clone(), message.clone());
    app.read(move |conn| {
        let app = app2;
        let presenter = Presenter::new(conn, &app, None);
        let view = presenter.message(&message)?;
        let account = campfire_db::Account::first(conn)?;
        let html = page::render_detached_at(&app, account.as_ref(), &base_url, |ctx| views::message(ctx, &view));
        let partials = Rendered { message: Some(html), ..Rendered::default() };
        app.broadcasts.message_create(conn, &room, &message, &partials)
    })
    .await
}

/// `broadcast_replace_to @room, :messages, target: [ @message, :presentation ], partial:
/// "messages/presentation", attributes: { maintain_scroll: true }`
pub(crate) async fn broadcast_replace(c: &Ctx, room: &Room, message: &Message) -> Result<()> {
    let (app, room, message) = (c.app().clone(), room.clone(), message.clone());
    let base_url = page::renderer_base_url(c);
    c.app()
        .read(move |conn| {
            let presenter = Presenter::new(conn, &app, None);
            let view = presenter.message(&message)?;
            let account = campfire_db::Account::first(conn)?;
            let html = page::render_detached_at(&app, account.as_ref(), &base_url, |ctx| {
                views::PresentationPartial { ctx, message: &view }.render()
            })
            .map_err(campfire_db::Error::other)?;
            let partials = Rendered { message_presentation: Some(html), ..Rendered::default() };
            app.broadcasts.message_replace(&room, &message, &partials);
            Ok(())
        })
        .await
}

