async fn open_form(c: &Ctx, room: FormRoom, can_administer: bool) -> Result<OpenFormView> {
    let secrets = c.app().secrets.clone();
    c.app().read_offloaded(move |conn| {
        let bot_ids: Vec<i64> = campfire_db::query_all(conn, "SELECT user_id FROM chat_bots", [], |r| r.get(0))?;
        let member_ids = match room.id {
            Some(id) => Room::find(conn, id)?.user_ids(conn)?,
            None => Vec::new(),
        };
        let mut users = Vec::new();
        let mut bots = Vec::new();
        for user in User::active_ordered(conn)? {
            let view = user_view(&secrets, &user);
            if bot_ids.contains(&user.id) {
                let automatic = Bot::find(conn, user.id)?.add_to_all_open_rooms;
                bots.push(OpenBotView { user: view, selected: automatic || member_ids.contains(&user.id), automatic });
            } else {
                users.push(view);
            }
        }
        Ok(OpenFormView { room, can_administer, users, bots })
    }).await
}

fn bot_ids_param(c: &Ctx) -> Option<Vec<i64>> {
    c.params.get("bot_ids").map(|param| {
        param.as_array().unwrap_or_default().iter()
            .filter_map(|id| id.to_s().and_then(|id| ruby_compat::integer_cast(&id))).collect()
    })
}

fn revise_bots(tx: &mut campfire_db::Tx<'_>, room: &Room, selected: Option<Vec<i64>>) -> campfire_db::Result<()> {
    let Some(selected) = selected else { return Ok(()) };
    // Only bot memberships can be changed here. People always keep open-room access,
    // and an opted-in bot cannot be removed from one open room in isolation.
    let bot_ids: Vec<i64> = campfire_db::query_all(tx.conn(),
        "SELECT b.user_id FROM chat_bots b JOIN users u ON u.id = b.user_id WHERE u.status = 0", [], |r| r.get(0))?;
    let (mut granted, mut revoked) = (Vec::new(), Vec::new());
    for id in bot_ids {
        if selected.contains(&id) || Bot::find(tx.conn(), id)?.add_to_all_open_rooms {
            granted.push(id);
        } else {
            revoked.push(id);
        }
    }
    room.revise(tx, &granted, &revoked)
}
