fn bot_ids_param(c: &Ctx) -> Option<Vec<i64>> {
    c.params.get("bot_ids").map(|param| {
        param.as_array().unwrap_or_default().iter().filter_map(|id| id.as_str()).filter_map(ruby_compat::integer_cast).collect()
    })
}

fn revise_bots(tx: &mut campfire_db::Tx<'_>, room: &Room, selected: Option<Vec<i64>>) -> campfire_db::Result<()> {
    let Some(selected) = selected else { return Ok(()) };
    // Only bot memberships can be changed here. People always keep open-room access,
    // and an opted-in bot cannot be removed from one open room in isolation.
    let bot_ids: Vec<i64> = campfire_db::query_all(
        tx.conn(),
        "SELECT b.user_id FROM chat_bots b JOIN users u ON u.id = b.user_id WHERE u.status = 0",
        [],
        |r| r.get(0),
    )?;
    let (mut granted, mut revoked) = (Vec::new(), Vec::new());
    for id in bot_ids {
        if selected.contains(&id) || Bot::find(tx.conn(), id)?.add_to_all_open_rooms {
            granted.push(id);
        } else {
            revoked.push(id);
        }
    }
    room.revise(tx, &granted, &revoked)
}
/// Memberships emit this only for the first non-direct join. Like mention callbacks,
/// delivery is best effort and never retried by the in-process job runner.
pub async fn joined(app: App, event: campfire_db::Event) -> anyhow::Result<()> {
    let campfire_db::Event::BotJoined { user_id, room_id } = event else { return Ok(()) };
    let delivery = app
        .db
        .read_offloaded(move |conn| {
            let bot = match Bot::find(conn, user_id) {
                Ok(bot) if bot.webhook_url.is_some() => bot,
                Ok(_) | Err(campfire_db::Error::RecordNotFound(_)) => return Ok(None),
                Err(error) => return Err(error),
            };
            let Some(room) = Room::find_for_user(conn, user_id, room_id)? else { return Ok(None) };
            if room.room_type == campfire_db::RoomType::Direct {
                return Ok(None);
            }
            let payload = json!({
                "event": "joined",
                "room": { "id": room.id, "name": room.name,
                    "reply_to": format!("/rooms/{}/{}/messages", room.id, bot.code) }
            });
            Ok(Some(Delivery { bot, room, payload }))
        })
        .await?;
    if let Some(delivery) = delivery {
        // There is no request host for database-triggered jobs. Broadcast relative URLs.
        deliver(&app, delivery, String::new()).await?;
    }
    Ok(())
}

